// 汇总本次抓取结果：按链接去重、按时间倒序、截取前 N 条
const crypto = require('crypto');
const seen = new Set();
const items = [];
for (const item of $input.all()) {
  const j = item.json;
  const link = String(j.link || '').trim();
  const title = String(j.title || '').trim();
  if (!link || !title) continue; // 跳过报错或空条目
  const key = link.split('?')[0];
  if (seen.has(key)) continue;
  seen.add(key);
  const summary = String(j.contentSnippet || j.content || '')
    .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1200);
  items.push({
    title, link, summary,
    source: String(j.source || '未知来源'),
    pubDate: j.isoDate || j.pubDate || new Date().toISOString(),
    slug: 'ai-' + crypto.createHash('md5').update(key).digest('hex').slice(0, 10)
  });
}
items.sort((a, b) => new Date(b.pubDate) - new Date(a.pubDate));
const max = $('配置').first().json.MAX_ITEMS_PER_RUN || 5;
const systemPrompt = '你是一位中文科技博客的资深编辑。请把用户给你的英文/中文 AI 资讯改写成一篇简体中文博客文章。要求：\n' +
  '1. 基于原文重新组织，不要逐句翻译，可补充背景说明；\n' +
  '2. 正文 300-600 字，可用 ## 小标题分节，不要出现 Markdown 代码块语法；\n' +
  '3. 只输出一个 JSON 对象，格式：{"title":"中文标题，30字以内","summary":"100字以内摘要","tags":["2-4个标签"],"markdown":"正文"}\n' +
  '4. 不要输出 JSON 以外的任何内容。';
const userPrompt = c => '资讯标题：' + c.title + '\n来源：' + c.source + '\n链接：' + c.link + '\n原文摘要：' + c.summary;
return [{ json: { candidates: items.slice(0, max).map(c => ({ ...c, systemPrompt, userPrompt: userPrompt(c) })) } }];

// 与 Notion 库中已有文章比对（slug 精确 + 标题归一化），跳过重复
const { candidates } = $('清洗与去重').first().json;
const results = $input.first().json?.results || [];
const norm = s => String(s || '').toLowerCase().replace(/[\s\p{P}]+/gu, '');
const slugs = new Set();
const titles = new Set();
for (const page of results) {
  const props = page.properties || {};
  for (const [k, v] of Object.entries(props)) {
    const key = k.toLowerCase();
    if (key === 'slug' && v.rich_text) slugs.add(v.rich_text.map(r => r.plain_text).join('').trim());
    if (key === 'title' && v.title) titles.add(norm(v.title.map(r => r.plain_text).join('')));
  }
}
return candidates
  .filter(c => !slugs.has(c.slug) && !titles.has(norm(c.title)))
  .map(c => ({ json: c }));

// 解析 AI 输出（容错：JSON 解析失败时用原文兜底），并构造 Notion 页面请求体
const cfg = $('配置').first().json;
const api = $input.first().json;
const cand = ($('过滤已存在').all()[$itemIndex] || {}).json || {};
let out = {};
const raw = String(api.choices?.[0]?.message?.content || '');
try {
  out = JSON.parse(raw.replace(/^\`\`\`(?:json)?/, '').replace(/\`\`\`$/, '').trim());
} catch (e) { out = {}; }

const title = String(out.title || cand.title || '未命名').slice(0, 60);
const summary = String(out.summary || cand.summary || '').slice(0, 180);
const tags = Array.isArray(out.tags) && out.tags.length
  ? out.tags.map(t => String(t).slice(0, 20)).slice(0, 4) : ['AI'];
const md = (out.markdown && String(out.markdown).trim())
  || (cand.summary || '正文生成失败，请查看原文：' + (cand.link || ''));

// 简易 Markdown -> Notion blocks（标题/列表/段落）
const blocks = [];
const push = (type, txt) => blocks.push({
  object: 'block', type,
  [type]: { rich_text: [{ type: 'text', text: { content: txt } }] }
});
for (const rawLine of md.split('\n')) {
  const t = rawLine.trim();
  if (!t) continue;
  if (t.startsWith('### ')) push('heading_3', t.slice(4));
  else if (t.startsWith('## ')) push('heading_2', t.slice(3));
  else if (t.startsWith('# ')) push('heading_1', t.slice(2));
  else if (t.startsWith('- ') || t.startsWith('* ')) push('bulleted_list_item', t.slice(2));
  else push('paragraph', t);
  if (blocks.length >= 80) break;
}

const notionBody = {
  parent: { database_id: cfg.NOTION_DATABASE_ID },
  properties: {
    title: { title: [{ text: { content: title } }] },
    status: { select: { name: 'Published' } },
    type: { select: { name: 'Post' } },
    summary: { rich_text: [{ text: { content: summary } }] },
    date: { date: { start: new Date().toISOString().slice(0, 10) } },
    category: { select: { name: cfg.CATEGORY } },
    tags: { multi_select: tags.map(name => ({ name })) },
    slug: { rich_text: [{ text: { content: cand.slug || slugFallback(cand.link || title) } }] }
  },
  children: blocks
};
function slugFallback(s) {
  return 'ai-' + require('crypto').createHash('md5').update(s).digest('hex').slice(0, 10);
}
return [{ json: { notionBody, title, slug: notionBody.properties.slug.rich_text[0].text.content } }];
